@Test
void roundTrip() throws Exception {
    final String text = longText();
    final AsyncEntityProducer raw = new StringAsyncEntityProducer(text, ContentType.TEXT_PLAIN);
    final DeflatingAsyncEntityProducer def = new DeflatingAsyncEntityProducer(raw);
    final ThrottledChannel ch = new ThrottledChannel(1024);
    while (def.available() > 0) {
        def.produce(ch);
    }
    final byte[] compressed = ch.data();
    assertTrue(compressed.length > 0);
    // Inflate (raw DEFLATE)
    final Inflater inflater = new Inflater(true);
    inflater.setInput(compressed);
    final ByteArrayOutputStream out = new ByteArrayOutputStream();
    final byte[] buf = new byte[8192];
    while (!inflater.finished()) {
        final int n = inflater.inflate(buf);
        if (n == 0 && inflater.needsInput())
            break;
        out.write(buf, 0, n);
    }
    inflater.end();
    assertEquals(text, out.toString("UTF-8"));
    assertEquals("deflate", def.getContentEncoding());
    assertTrue(def.isChunked());
    assertEquals(-1, def.getContentLength());
}

@Test
void roundTrip() throws Exception {
    final String text = longText();
    final byte[] payload = text.getBytes(java.nio.charset.StandardCharsets.UTF_8);
    final AsyncEntityProducer raw = new org.apache.hc.core5.http.nio.entity.BasicAsyncEntityProducer(payload, org.apache.hc.core5.http.ContentType.TEXT_PLAIN.withCharset(java.nio.charset.StandardCharsets.UTF_8));
    final DeflatingBrotliEntityProducer br = new DeflatingBrotliEntityProducer(raw, 5, 22, Encoder.Mode.TEXT);
    final ThrottledChannel ch = new ThrottledChannel(1024);
    // drive until producer reports no more work
    while (br.available() > 0) {
        br.produce(ch);
    }
    final byte[] compressed = ch.data();
    assertTrue(compressed.length > 0, "no compressed bytes were produced");
    // Decompress using brotli4j
    final DirectDecompress dd = Decoder.decompress(compressed);
    final String decoded = new String(dd.getDecompressedData(), StandardCharsets.UTF_8);
    assertEquals(text, decoded);
    assertEquals("br", br.getContentEncoding());
    assertTrue(br.isChunked());
    assertEquals(-1, br.getContentLength());
    assertTrue(ch.ended(), "stream was not ended");
}

