@Test
void gzipCompress() throws Exception {
    final AsyncEntityProducer json = new StringAsyncEntityProducer("\"" + TEXT + "\"", ContentType.APPLICATION_JSON);
    final AsyncEntityProducer gzipProd = new DeflatingGzipEntityProducer(json);
    /* collect bytes “on the wire” */
    final ByteArrayOutputStream wire = new ByteArrayOutputStream();
    final CountDownLatch done = new CountDownLatch(1);
    gzipProd.produce(new DataStreamChannel() {

        @Override
        public void requestOutput() {
        }

        @Override
        public int write(final ByteBuffer src) {
            final byte[] tmp = new byte[src.remaining()];
            src.get(tmp);
            wire.write(tmp, 0, tmp.length);
            return tmp.length;
        }

        @Override
        public void endStream() {
            done.countDown();
        }

        @Override
        public void endStream(final List<? extends Header> t) {
            endStream();
        }
    });
    if (!done.await(2, TimeUnit.SECONDS)) {
        fail("producer timed-out");
    }
    /* verify round-trip */
    final ByteArrayInputStream bin = new ByteArrayInputStream(wire.toByteArray());
    final ByteArrayOutputStream bout = new ByteArrayOutputStream();
    final byte[] buf = new byte[4096];
    try (final GZIPInputStream gin = new GZIPInputStream(bin)) {
        int n;
        while ((n = gin.read(buf)) != -1) {
            bout.write(buf, 0, n);
        }
    }
    final String roundTrip = bout.toString(StandardCharsets.UTF_8.name());
    assertEquals("\"" + TEXT + "\"", roundTrip);
}

@Test
void inflateRawAndZlib() throws Exception {
    for (final boolean nowrap : new boolean[] { true, false }) {
        final byte[] compressed = compress(nowrap);
        final ByteCollector inner = new ByteCollector();
        final InflatingAsyncDataConsumer inflating = new InflatingAsyncDataConsumer(inner, Boolean.valueOf(nowrap));
        final CountDownLatch done = new CountDownLatch(1);
        final FutureCallback<String> cb = new FutureCallback<String>() {

            @Override
            public void completed(final String result) {
                done.countDown();
            }

            @Override
            public void failed(final Exception ex) {
                fail(ex);
            }

            @Override
            public void cancelled() {
                fail("cancelled");
            }
        };
        /* minimal EntityDetails stub */
        final EntityDetails details = new EntityDetails() {

            @Override
            public long getContentLength() {
                return compressed.length;
            }

            @Override
            public String getContentType() {
                return "text/plain";
            }

            @Override
            public String getContentEncoding() {
                return "deflate";
            }

            @Override
            public boolean isChunked() {
                return false;
            }

            @Override
            public Set<String> getTrailerNames() {
                return new HashSet<>();
            }
        };
        inner.streamStart(details, cb);
        for (int off = 0; off < compressed.length; off += 1024) {
            final int n = Math.min(1024, compressed.length - off);
            inflating.consume(ByteBuffer.wrap(compressed, off, n));
        }
        inflating.streamEnd(Collections.emptyList());
        assertTrue(done.await(2, TimeUnit.SECONDS), "callback timeout");
        assertEquals(ORIGINAL, inner.getContent(), (nowrap ? "raw" : "zlib") + " inflate mismatch");
    }
}

