    final FormBodyPart p2 = FormBodyPartBuilder.create("field2", new StringBody("that stuff", ContentType.create(ContentType.TEXT_PLAIN.getMimeType(), StandardCharsets.ISO_8859_1))).build();
    final FormBodyPart p3 = FormBodyPartBuilder.create("field3", new StringBody("all kind of stuff", ContentType.DEFAULT_TEXT)).build();
    final HttpStrictMultipart multipart = new HttpStrictMultipart(null, "foo", Arrays.asList(p1, p2, p3));
    final ByteArrayOutputStream out = new ByteArrayOutputStream();
    multipart.writeTo(out);
    out.close();
    final String expected = "--foo
" + "Content-Disposition: form-data; name="field1"
" + "Content-Type: text/plain; charset=UTF-8
" + "
" + "this stuff
" + "--foo
" + "Content-Disposition: form-data; name="field2"
" + "Content-Type: text/plain; charset=ISO-8859-1
" + "
" + "that stuff
" + "--foo
" + "Content-Disposition: form-data; name="field3"
" + "Content-Type: text/plain; charset=UTF-8
" + "
" + "all kind of stuff
" + "--foo--
";
    final String s = out.toString("US-ASCII");
    Assertions.assertEquals(expected, s);
    Assertions.assertEquals(s.length(), multipart.getTotalLength());
}

