    Assertions.assertFalse(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("someotherhost", 1234), BasicRequestBuilder.get("/").addHeader(HttpHeaders.AUTHORIZATION, "let me pass").build(), null));
    Assertions.assertFalse(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("someotherhost", 1234), BasicRequestBuilder.get("/").addHeader(HttpHeaders.COOKIE, "stuff=blah").build(), null));
    Assertions.assertFalse(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("somehost", 80), BasicRequestBuilder.get("/").addHeader(HttpHeaders.AUTHORIZATION, "let me pass").build(), null));
