    final HttpHost explicitHttps = new HttpHost("https", "example.com", 443);
    final HttpHost implicitHttps = new HttpHost("https", "example.com", -1);
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(explicitHttps, implicitHttps, BasicRequestBuilder.get("/").addHeader(HttpHeaders.AUTHORIZATION, "token").build(), null));
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(implicitHttps, explicitHttps, BasicRequestBuilder.get("/").addHeader(HttpHeaders.COOKIE, "cookie=123").build(), null));
    final HttpHost explicitHttp = new HttpHost("http", "example.org", 80);
    final HttpHost implicitHttp = new HttpHost("http", "example.org", -1);
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(explicitHttp, implicitHttp, BasicRequestBuilder.get("/").addHeader(HttpHeaders.AUTHORIZATION, "token123").build(), null));
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(implicitHttp, explicitHttp, BasicRequestBuilder.get("/").addHeader(HttpHeaders.COOKIE, "cookie=abc").build(), null));
}

@Test
void testEvictExpiredAndIdle() throws Exception {
    final ConnPoolControl<?> cm = Mockito.mock(ConnPoolControl.class);
    final IdleConnectionEvictor connectionEvictor = new IdleConnectionEvictor(cm, TimeValue.ofMilliseconds(500), TimeValue.ofSeconds(3));
    connectionEvictor.start();
    Thread.sleep(1000);
    Mockito.verify(cm, Mockito.atLeast(1)).closeExpired();
    Mockito.verify(cm, Mockito.atLeast(1)).closeIdle(TimeValue.ofSeconds(3));
    Assertions.assertTrue(connectionEvictor.isRunning());
    connectionEvictor.shutdown();
    connectionEvictor.awaitTermination(Timeout.ofSeconds(1));
    Assertions.assertFalse(connectionEvictor.isRunning());
}

