/**
 * Test {@link LaxRedirectStrategy#isRedirectAllowed(HttpHost, HttpHost, HttpRequest, HttpContext)}.
 * The method should return true for all requests, enabling backward compatibility.
 */
@Test
void testRedirectAllowed() throws Exception {
    final LaxRedirectStrategy redirectStrategy = new LaxRedirectStrategy();
    // Same host and port
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("somehost", 1234), BasicRequestBuilder.get("/").build(), null));
    // Same host and port with Authorization header
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("somehost", 1234), BasicRequestBuilder.get("/").addHeader(HttpHeaders.AUTHORIZATION, "let me pass").build(), null));
    // Same host and port with Cookie header
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("somehost", 1234), BasicRequestBuilder.get("/").addHeader(HttpHeaders.COOKIE, "stuff=blah").build(), null));
    // Different host and same port
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("someotherhost", 1234), BasicRequestBuilder.get("/").build(), null));
    // Different host and same port with Authorization header
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("someotherhost", 1234), BasicRequestBuilder.get("/").addHeader(HttpHeaders.AUTHORIZATION, "let me pass").build(), null));
    // Different host and same port with Cookie header
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("someotherhost", 1234), BasicRequestBuilder.get("/").addHeader(HttpHeaders.COOKIE, "stuff=blah").build(), null));
    // Same host and different ports with Authorization header
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("somehost", 80), BasicRequestBuilder.get("/").addHeader(HttpHeaders.AUTHORIZATION, "let me pass").build(), null));
    // Same host and different ports with Cookie header
    Assertions.assertTrue(redirectStrategy.isRedirectAllowed(new HttpHost("somehost", 1234), new HttpHost("somehost", 80), BasicRequestBuilder.get("/").addHeader(HttpHeaders.COOKIE, "stuff=blah").build(), null));
}

