@Test
void testUpgrade() throws Exception {
    final HttpRequest get = new BasicHttpRequest("GET", "/");
    interceptor.process(get, null, context);
    MatcherAssert.assertThat(get.getHeaders(), HeadersMatcher.same(new BasicHeader(HttpHeaders.UPGRADE, "TLS/1.2"), new BasicHeader(HttpHeaders.CONNECTION, HttpHeaders.UPGRADE)));
    final HttpRequest options = new BasicHttpRequest("OPTIONS", "/");
    interceptor.process(options, null, context);
    MatcherAssert.assertThat(options.getHeaders(), HeadersMatcher.same(new BasicHeader(HttpHeaders.UPGRADE, "TLS/1.2"), new BasicHeader(HttpHeaders.CONNECTION, HttpHeaders.UPGRADE)));
    final HttpRequest head = new BasicHttpRequest("HEAD", "/");
    interceptor.process(head, null, context);
    MatcherAssert.assertThat(head.getHeaders(), HeadersMatcher.same(new BasicHeader(HttpHeaders.UPGRADE, "TLS/1.2"), new BasicHeader(HttpHeaders.CONNECTION, HttpHeaders.UPGRADE)));
}

