    Mockito.verify(impl, Mockito.times(2)).getStorageObject("stuff");
    Mockito.verify(impl, Mockito.times(2)).updateCAS(ArgumentMatchers.eq("bar"), ArgumentMatchers.eq("stuff"), ArgumentMatchers.any(), ArgumentMatchers.any());
