    final HttpResponse resp1 = HttpTestUtils.make200Response();
    resp1.setHeader("Date", DateUtils.formatStandardDate(tenSecondsAgo));
    resp1.setHeader("Cache-Control", "max-age=3600, public");
    resp1.setHeader("ETag", "\"etag1\"");
