    request = BasicRequestBuilder.get("/foo").addHeader("Accept-Encoding", "gzip, deflate, deflate ,  zip, ").build();
    entry = makeEntry(Method.GET, "/foo", new Header[] { new BasicHeader("Accept-Encoding", " gzip, zip, deflate") }, 200, new Header[] { new BasicHeader("Date", DateUtils.formatStandardDate(tenSecondsAgo)), new BasicHeader("Vary", "Accept-Encoding") });
