@Test
void testSuitableIfErrorRequestCacheControl() {
    // Prepare a cache entry with HEAD method
    entry = makeEntry(Method.GET, "/foo", new BasicHeader("Date", DateUtils.formatStandardDate(tenSecondsAgo)));
    responseCacheControl = ResponseCacheControl.builder().setMaxAge(5).build();
    // the entry has been stale for 6 seconds
    requestCacheControl = RequestCacheControl.builder().setStaleIfError(10).build();
    Assertions.assertTrue(impl.isSuitableIfError(requestCacheControl, responseCacheControl, entry, now));
    requestCacheControl = RequestCacheControl.builder().setStaleIfError(5).build();
    Assertions.assertFalse(impl.isSuitableIfError(requestCacheControl, responseCacheControl, entry, now));
    requestCacheControl = RequestCacheControl.builder().setStaleIfError(10).setMinFresh(// should take precedence over stale-if-error
    4).build();
    Assertions.assertFalse(impl.isSuitableIfError(requestCacheControl, responseCacheControl, entry, now));
    requestCacheControl = RequestCacheControl.builder().setStaleIfError(// not set or not valid
    -1).build();
    Assertions.assertFalse(impl.isSuitableIfError(requestCacheControl, responseCacheControl, entry, now));
}

