@Test
void testNormalizeHeaderElements() {
    final List<String> tokens = new ArrayList<>();
    CacheKeyGenerator.normalizeElements(headers(new BasicHeader("Accept-Encoding", "gzip,zip,deflate")), tokens::add);
    Assertions.assertEquals(Arrays.asList("deflate", "gzip", "zip"), tokens);
    tokens.clear();
    CacheKeyGenerator.normalizeElements(headers(new BasicHeader("Accept-Encoding", "  gZip  , Zip,  ,  ,  deflate  ")), tokens::add);
    Assertions.assertEquals(Arrays.asList("deflate", "gzip", "zip"), tokens);
    tokens.clear();
    CacheKeyGenerator.normalizeElements(headers(new BasicHeader("Accept-Encoding", "gZip,Zip,,"), new BasicHeader("Accept-Encoding", "   gZip,Zip,,,"), new BasicHeader("Accept-Encoding", "gZip,  ,,,deflate")), tokens::add);
    Assertions.assertEquals(Arrays.asList("deflate", "gzip", "zip"), tokens);
    tokens.clear();
    CacheKeyGenerator.normalizeElements(headers(new BasicHeader("Cookie", "name1 = value1 ;   p1 = v1 ; P2   = \"v2\""), new BasicHeader("Cookie", "name3;;;"), new BasicHeader("Cookie", "   name2 = \" value 2 \"   ; ; ; ,,,")), tokens::add);
    Assertions.assertEquals(Arrays.asList("name1=value1;p1=v1;p2=v2", "name2=\" value 2 \"", "name3"), tokens);
}

