@Test
void testIssue1147() throws Exception {
    final CacheConfig cacheConfig = CacheConfig.custom().setSharedCache(true).setMaxObjectSize(//256kb
    262144).build();
    final ResourceFactory resourceFactory = new FileResourceFactory(cacheDir);
    final HttpCacheStorage httpCacheStorage = new ManagedHttpCacheStorage(cacheConfig);
    final ExecChain mockExecChain = mock(ExecChain.class);
    final ExecRuntime mockEndpoint = mock(ExecRuntime.class);
    final HttpHost target = new HttpHost("somehost", 80);
    final HttpRoute route = new HttpRoute(target);
    final ClassicHttpRequest get = new HttpGet("http://somehost/");
    final HttpCacheContext context = HttpCacheContext.create();
    final Instant now = Instant.now();
    final Instant tenSecondsAgo = now.minusSeconds(10);
    final ClassicHttpResponse response = new BasicClassicHttpResponse(200, "OK");
    response.setEntity(HttpTestUtils.makeBody(128));
    response.setHeader("Content-Length", "128");
    response.setHeader("ETag", "\"etag\"");
    response.setHeader("Cache-Control", "public, max-age=3600");
    response.setHeader("Last-Modified", DateUtils.formatStandardDate(tenSecondsAgo));
    when(mockExecChain.proceed(isA(ClassicHttpRequest.class), isA(ExecChain.Scope.class))).thenReturn(response);
    final BasicHttpCache cache = new BasicHttpCache(resourceFactory, httpCacheStorage);
    final ExecChainHandler t = createCachingExecChain(cache, cacheConfig);
    final ExecChain.Scope scope = new ExecChain.Scope("teset", route, get, mockEndpoint, context);
    final ClassicHttpResponse response1 = t.execute(get, scope, mockExecChain);
    Assertions.assertEquals(200, response1.getCode());
    EntityUtils.consume(response1.getEntity());
    verify(mockExecChain).proceed(isA(ClassicHttpRequest.class), isA(ExecChain.Scope.class));
    removeCache();
    reset(mockExecChain);
    when(mockExecChain.proceed(isA(ClassicHttpRequest.class), isA(ExecChain.Scope.class))).thenReturn(response);
    final ClassicHttpResponse response2 = t.execute(get, scope, mockExecChain);
    Assertions.assertEquals(200, response2.getCode());
    EntityUtils.consume(response2.getEntity());
    verify(mockExecChain, Mockito.times(1)).proceed(isA(ClassicHttpRequest.class), isA(ExecChain.Scope.class));
    Assertions.assertEquals(CacheResponseStatus.FAILURE, context.getCacheResponseStatus());
}

@Test
void testCacheBasics() {
    final InternalCacheStorage storage = new InternalCacheStorage();
    final String key1 = "some-key-1";
    Assertions.assertNull(storage.get(key1));
    Assertions.assertNull(storage.remove(key1));
    final HttpCacheEntry entry1 = HttpTestUtils.makeCacheEntry();
    storage.put(key1, entry1);
    Assertions.assertSame(entry1, storage.get(key1));
    Assertions.assertSame(entry1, storage.remove(key1));
    Assertions.assertNull(storage.get(key1));
    Assertions.assertNull(storage.remove(key1));
    final String key2 = "some-key-2";
    final HttpCacheEntry entry2 = HttpTestUtils.makeCacheEntry();
    final String key3 = "some-key-3";
    final HttpCacheEntry entry3 = HttpTestUtils.makeCacheEntry();
    storage.put(key2, entry2);
    storage.put(key3, entry3);
    Assertions.assertSame(entry2, storage.get(key2));
    Assertions.assertSame(entry3, storage.get(key3));
    storage.clear();
    Assertions.assertNull(storage.get(key2));
    Assertions.assertNull(storage.get(key3));
}

@Test
void testCacheEviction() {
    final Queue<HttpCacheEntry> evictedEntries = new LinkedList<>();
    final InternalCacheStorage storage = new InternalCacheStorage(2, e -> evictedEntries.add(e.getContent()));
    final String key1 = "some-key-1";
    final String key2 = "some-key-2";
    final String key3 = "some-key-3";
    final String key4 = "some-key-4";
    final HttpCacheEntry entry1 = HttpTestUtils.makeCacheEntry();
    final HttpCacheEntry entry2 = HttpTestUtils.makeCacheEntry();
    final HttpCacheEntry entry3 = HttpTestUtils.makeCacheEntry();
    final HttpCacheEntry entry4 = HttpTestUtils.makeCacheEntry();
    storage.put(key1, entry1);
    storage.put(key2, entry2);
    storage.put(key3, entry3);
    storage.put(key4, entry4);
    Assertions.assertSame(entry1, evictedEntries.poll());
    Assertions.assertSame(entry2, evictedEntries.poll());
    Assertions.assertNull(evictedEntries.poll());
    storage.clear();
    storage.put(key1, entry1);
    storage.put(key2, entry2);
    storage.get(key1);
    storage.put(key3, entry3);
    storage.get(key1);
    storage.put(key4, entry4);
    Assertions.assertSame(entry2, evictedEntries.poll());
    Assertions.assertSame(entry3, evictedEntries.poll());
    Assertions.assertNull(evictedEntries.poll());
}

