@Test
void testPush() throws Exception {
    configureServer(bootstrap -> bootstrap.register("/pushy", () -> new AbstractServerExchangeHandler<HttpRequest>() {

        @Override
        protected AsyncRequestConsumer<HttpRequest> supplyConsumer(final HttpRequest request, final EntityDetails entityDetails, final HttpContext context) throws HttpException {
            return new AbstractAsyncRequesterConsumer<HttpRequest, Void>(new DiscardingEntityConsumer<>()) {

                @Override
                protected HttpRequest buildResult(final HttpRequest request, final Void entity, final ContentType contentType) {
                    return request;
                }
            };
        }

        @Override
        protected void handle(final HttpRequest request, final AsyncServerRequestHandler.ResponseTrigger responseTrigger, final HttpContext context) throws HttpException, IOException {
            responseTrigger.pushPromise(BasicRequestBuilder.copy(request).setPath("/aaa").build(), context, new BasicPushProducer(BasicResponseBuilder.create(HttpStatus.SC_OK).build(), new StringAsyncEntityProducer("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", ContentType.TEXT_PLAIN)));
            responseTrigger.pushPromise(BasicRequestBuilder.copy(request).setPath("/bbb").build(), context, new BasicPushProducer(BasicResponseBuilder.create(HttpStatus.SC_OK).build(), new StringAsyncEntityProducer("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbb", ContentType.TEXT_PLAIN)));
            responseTrigger.submitResponse(new BasicResponseProducer(BasicResponseBuilder.create(HttpStatus.SC_OK).build(), new StringAsyncEntityProducer("I am being very pushy")), context);
        }
    }));
    configureClient(builder -> builder.setH2Config(H2Config.custom().setPushEnabled(true).build()));
    final HttpHost target = startServer();
    final TestAsyncClient client = startClient();
    client.start();
    final Queue<Result<String>> pushMessageQueue = new ConcurrentLinkedQueue<>();
    final CountDownLatch latch = new CountDownLatch(3);
    final HttpClientContext context = HttpClientContext.create();
    final SimpleHttpRequest request = SimpleRequestBuilder.get().setHttpHost(target).setPath("/pushy").build();
    client.execute(SimpleRequestProducer.create(request), SimpleResponseConsumer.create(), (r, c) -> new AbstractAsyncPushHandler<SimpleHttpResponse>(SimpleResponseConsumer.create()) {

        @Override
        protected void handleResponse(final HttpRequest promise, final SimpleHttpResponse response) throws IOException, HttpException {
            pushMessageQueue.add(new Result<>(promise, response, response.getBodyText()));
            latch.countDown();
        }

        @Override
        protected void handleError(final HttpRequest promise, final Exception cause) {
            pushMessageQueue.add(new Result<>(promise, cause));
            latch.countDown();
        }
    }, context, new FutureCallback<SimpleHttpResponse>() {

        @Override
        public void completed(final SimpleHttpResponse response) {
            pushMessageQueue.add(new Result<>(request, response, response.getBodyText()));
            latch.countDown();
        }

        @Override
        public void failed(final Exception ex) {
            pushMessageQueue.add(new Result<>(request, ex));
            latch.countDown();
        }

        @Override
        public void cancelled() {
            pushMessageQueue.add(new Result<>(request, new RequestNotExecutedException()));
            latch.countDown();
        }
    });
    Assertions.assertTrue(latch.await(TIMEOUT.getDuration(), TIMEOUT.getTimeUnit()));
    Assertions.assertEquals(3, pushMessageQueue.size());
    for (final Result<String> result : pushMessageQueue) {
        if (result.isOK()) {
            Assertions.assertEquals(HttpStatus.SC_OK, result.response.getCode());
            final String path = result.request.getPath();
            if (path.equals("/pushy")) {
                Assertions.assertEquals("I am being very pushy", result.content);
            } else if (path.equals("/aaa")) {
                Assertions.assertEquals("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", result.content);
            } else if (path.equals("/bbb")) {
                Assertions.assertEquals("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbb", result.content);
            } else {
                Assertions.fail("Unxpected request path: " + path);
            }
        }
    }
}

