void testReadTimeouts(final String param) throws Throwable {
    checkAssumptions();
    final String[] params = param.split(",");
    final int connConfigTimeout = Integer.parseInt(params[0]);
    final long responseTimeout = Integer.parseInt(params[1]);
    final long expectedDelayMs = Long.parseLong(params[2]);
    final boolean drip = Boolean.parseBoolean(params[3]);
    configureServer(bootstrap -> bootstrap.register("/random/*", AsyncRandomHandler::new));
    final HttpHost target = startServer();
    final TestAsyncClient client = startClient();
    final PoolingAsyncClientConnectionManager connManager = client.getConnectionManager();
    if (connConfigTimeout > 0) {
        connManager.setDefaultConnectionConfig(ConnectionConfig.custom().setSocketTimeout(connConfigTimeout, MILLISECONDS).build());
    }
    final SimpleHttpRequest request = SimpleHttpRequest.create(Method.GET, target, "/random/10240?delay=500&drip=" + (drip ? 1 : 0));
    if (responseTimeout > 0) {
        request.setConfig(RequestConfig.custom().setUnixDomainSocket(getUnixDomainSocket()).setResponseTimeout(responseTimeout, MILLISECONDS).build());
    }
    final long startTime = System.nanoTime();
    final Throwable cause = assertThrows(ExecutionException.class, () -> client.execute(request, null).get()).getCause();
    final long actualDelayMs = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startTime);
    assertInstanceOf(SocketTimeoutException.class, cause);
    assertTrue(actualDelayMs > expectedDelayMs / 2, format("Socket read timed out too soon (only %,d out of %,d ms)", actualDelayMs, expectedDelayMs));
    assertTrue(actualDelayMs < expectedDelayMs * 2, format("Socket read timed out too late (%,d out of %,d ms)", actualDelayMs, expectedDelayMs));
    closeClient(client);
}

@Timeout(5)
@ParameterizedTest
@ValueSource(strings = { "false", "true" })
void testTimeout(final boolean sendServerHello) throws Exception {
    // There is a bug in Java 11: after the handshake times out, the SSLSocket implementation performs a blocking
    // read on the socket to wait for close_notify or alert. This operation blocks until the read times out,
    // which means that TLS handshakes take twice as long to time out on Java 11. Without a workaround, the only
    // option is to skip the timeout duration assertions on Java 11.
    assumeFalse(determineJRELevel() == 11, "TLS handshake timeouts are buggy on Java 11");
    final PoolingAsyncClientConnectionManager connMgr = PoolingAsyncClientConnectionManagerBuilder.create().setDefaultConnectionConfig(ConnectionConfig.custom().setConnectTimeout(5, SECONDS).setSocketTimeout(5, SECONDS).build()).setTlsStrategy(new DefaultClientTlsStrategy(SSLTestContexts.createClientSSLContext())).setDefaultTlsConfig(TlsConfig.custom().setHandshakeTimeout(EXPECTED_TIMEOUT.toMillis(), MILLISECONDS).build()).build();
    try (final TlsHandshakeTimeoutServer server = new TlsHandshakeTimeoutServer(sendServerHello);
        final CloseableHttpAsyncClient client = HttpAsyncClientBuilder.create().setIOReactorConfig(IOReactorConfig.custom().setSelectInterval(TimeValue.ofMilliseconds(50)).build()).setConnectionManager(connMgr).build()) {
        server.start();
        client.start();
        final SimpleHttpRequest request = SimpleHttpRequest.create("GET", "https://127.0.0.1:" + server.getPort());
        assertTimeout(request, client);
    }
}

