@Test
void testBearerTokenAuthentication() throws Exception {
    final SecureRandom secureRandom = SecureRandom.getInstanceStrong();
    secureRandom.setSeed(System.currentTimeMillis());
    final StringBuilder buf = new StringBuilder();
    for (int i = 0; i < 16; i++) {
        buf.append(CHARS.charAt(secureRandom.nextInt(CHARS.length() - 1)));
    }
    final String token = buf.toString();
    configureServer(bootstrap -> bootstrap.setExchangeHandlerDecorator(requestHandler -> new AuthenticatingDecorator(requestHandler, new BearerAuthenticationHandler(), new BasicTestAuthenticator(token, "test realm"))).register("*", new EchoHandler()));
    final HttpHost target = startServer();
    final TestClient client = client();
    final CredentialsProvider credsProvider = Mockito.mock(CredentialsProvider.class);
    final HttpClientContext context1 = HttpClientContext.create();
    context1.setCredentialsProvider(credsProvider);
    final HttpGet httpget1 = new HttpGet("/");
    client.execute(target, httpget1, context1, response -> {
        final HttpEntity entity = response.getEntity();
        Assertions.assertEquals(HttpStatus.SC_UNAUTHORIZED, response.getCode());
        Assertions.assertNotNull(entity);
        EntityUtils.consume(entity);
        return null;
    });
    Mockito.verify(credsProvider).getCredentials(Mockito.eq(new AuthScope(target, "test realm", "bearer")), Mockito.any());
    final HttpClientContext context2 = HttpClientContext.create();
    Mockito.when(credsProvider.getCredentials(Mockito.any(), Mockito.any())).thenReturn(new BearerToken(token));
    context2.setCredentialsProvider(credsProvider);
    final HttpGet httpget2 = new HttpGet("/");
    client.execute(target, httpget2, context2, response -> {
        final HttpEntity entity = response.getEntity();
        Assertions.assertEquals(HttpStatus.SC_OK, response.getCode());
        Assertions.assertNotNull(entity);
        EntityUtils.consume(entity);
        return null;
    });
    final HttpClientContext context3 = HttpClientContext.create();
    Mockito.when(credsProvider.getCredentials(Mockito.any(), Mockito.any())).thenReturn(new BearerToken(token + "-expired"));
    context3.setCredentialsProvider(credsProvider);
    final HttpGet httpget3 = new HttpGet("/");
    client.execute(target, httpget3, context3, response -> {
        final HttpEntity entity = response.getEntity();
        Assertions.assertEquals(HttpStatus.SC_UNAUTHORIZED, response.getCode());
        Assertions.assertNotNull(entity);
        EntityUtils.consume(entity);
        return null;
    });
}

@Test
void testAutoGeneratedHeaders() throws Exception {
    configureServer(bootstrap -> bootstrap.register("*", new SimpleService()));
    final HttpHost target = startServer();
    final HttpRequestInterceptor interceptor = (request, entityDetails, context) -> request.addHeader("my-header", "stuff");
    final HttpRequestRetryStrategy requestRetryStrategy = new HttpRequestRetryStrategy() {

        @Override
        public boolean retryRequest(final HttpRequest request, final IOException exception, final int executionCount, final HttpContext context) {
            return true;
        }

        @Override
        public boolean retryRequest(final HttpResponse response, final int executionCount, final HttpContext context) {
            return false;
        }

        @Override
        public TimeValue getRetryInterval(final HttpResponse response, final int executionCount, final HttpContext context) {
            return TimeValue.ofSeconds(1L);
        }
    };
    configureClient(builder -> builder.addRequestInterceptorFirst(interceptor).setRequestExecutor(new FaultyHttpRequestExecutor("Oppsie")).setRetryStrategy(requestRetryStrategy));
    final TestClient client = client();
    final HttpClientContext context = HttpClientContext.create();
    final HttpGet httpget = new HttpGet("/");
    client.execute(target, httpget, context, response -> {
        EntityUtils.consume(response.getEntity());
        final HttpRequest reqWrapper = context.getRequest();
        Assertions.assertEquals(HttpStatus.SC_OK, response.getCode());
        final Header[] myheaders = reqWrapper.getHeaders("my-header");
        Assertions.assertNotNull(myheaders);
        Assertions.assertEquals(1, myheaders.length);
        return null;
    });
}

