@Timeout(5)
@ParameterizedTest
@ValueSource(strings = { "150,0,0,150,false", "0,150,0,150,false", "150,0,0,150,true", "0,150,0,150,true", // ConnectionConfig overrides SocketConfig
"50,150,0,150,false", "1000,150,0,150,false", "50,150,0,150,true", "1000,150,0,150,true", // ResponseTimeout overrides socket timeout
"2000,2000,150,150,false", "2000,2000,150,150,true" })
void testReadTimeouts(final String param) throws Exception {
    final String[] params = param.split(",");
    final int socketConfigTimeout = Integer.parseInt(params[0]);
    final int connConfigTimeout = Integer.parseInt(params[1]);
    final long responseTimeout = Integer.parseInt(params[2]);
    final long expectedDelayMs = Long.parseLong(params[3]);
    final boolean drip = Boolean.parseBoolean(params[4]);
    configureServer(bootstrap -> bootstrap.register("/random/*", new RandomHandler()));
    final HttpHost target = startServer();
    final TestClient client = client();
    final PoolingHttpClientConnectionManager connManager = client.getConnectionManager();
    if (socketConfigTimeout > 0) {
        connManager.setDefaultSocketConfig(SocketConfig.custom().setSoTimeout(socketConfigTimeout, MILLISECONDS).build());
    }
    if (connConfigTimeout > 0) {
        connManager.setDefaultConnectionConfig(ConnectionConfig.custom().setSocketTimeout(connConfigTimeout, MILLISECONDS).build());
    }
    final HttpGet request = new HttpGet(new URI("/random/10240?delay=1000&drip=" + (drip ? 1 : 0)));
    if (responseTimeout > 0) {
        request.setConfig(RequestConfig.custom().setUnixDomainSocket(getUnixDomainSocket()).setResponseTimeout(responseTimeout, MILLISECONDS).build());
    }
    final long startTime = System.nanoTime();
    assertThrows(SocketTimeoutException.class, () -> client.execute(target, request, new BasicHttpClientResponseHandler()));
    final long actualDelayMs = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startTime);
    assertTrue(actualDelayMs > expectedDelayMs / 2, format("Socket read timed out too soon (only %,d out of %,d ms)", actualDelayMs, expectedDelayMs));
    assertTrue(actualDelayMs < expectedDelayMs * 3, format("Socket read timed out too late (%,d out of %,d ms)", actualDelayMs, expectedDelayMs));
}

@Test
void testStatefulConnections() throws Exception {
    configureServer(bootstrap -> bootstrap.register("*", new SimpleService()));
    final HttpHost target = startServer();
    final int workerCount = 5;
    final int requestCount = 5;
    final UserTokenHandler userTokenHandler = (route, context) -> {
        final String id = (String) context.getAttribute("user");
        return id;
    };
    configureClient(builder -> builder.setUserTokenHandler(userTokenHandler));
    final TestClient client = client();
    final PoolingHttpClientConnectionManager connectionManager = client.getConnectionManager();
    connectionManager.setMaxTotal(workerCount);
    connectionManager.setDefaultMaxPerRoute(workerCount);
    final HttpClientContext[] contexts = new HttpClientContext[workerCount];
    final HttpWorker[] workers = new HttpWorker[workerCount];
    for (int i = 0; i < contexts.length; i++) {
        final HttpClientContext context = HttpClientContext.create();
        contexts[i] = context;
        workers[i] = new HttpWorker("user" + i, context, requestCount, target, client);
    }
    for (final HttpWorker worker : workers) {
        worker.start();
    }
    for (final HttpWorker worker : workers) {
        worker.join(LONG_TIMEOUT.toMilliseconds());
    }
    for (final HttpWorker worker : workers) {
        final Exception ex = worker.getException();
        if (ex != null) {
            throw ex;
        }
        Assertions.assertEquals(requestCount, worker.getCount());
    }
    for (final HttpContext context : contexts) {
        final String state0 = (String) context.getAttribute("r0");
        Assertions.assertNotNull(state0);
        for (int r = 1; r < requestCount; r++) {
            Assertions.assertEquals(state0, context.getAttribute("r" + r));
        }
    }
}

@Test
void testRouteSpecificPoolRecylcing() throws Exception {
    configureServer(bootstrap -> bootstrap.register("*", new SimpleService()));
    final HttpHost target = startServer();
    // This tests what happens when a maxed connection pool needs
    // to kill the last idle connection to a route to build a new
    // one to the same route.
    final int maxConn = 2;
    configureClient(builder -> builder.setUserTokenHandler((route, context) -> context.getAttribute("user")));
    final TestClient client = client();
    final PoolingHttpClientConnectionManager connectionManager = client.getConnectionManager();
    connectionManager.setMaxTotal(maxConn);
    connectionManager.setDefaultMaxPerRoute(maxConn);
    // Bottom of the pool : a *keep alive* connection to Route 1.
    final HttpContext context1 = HttpClientContext.create();
    context1.setAttribute("user", "stuff");
    client.execute(target, new HttpGet("/"), context1, response -> {
        EntityUtils.consume(response.getEntity());
        return null;
    });
    // The ConnPoolByRoute now has 1 free connection, out of 2 max
    // The ConnPoolByRoute has one RouteSpcfcPool, that has one free connection
    // for [localhost][stuff]
    Thread.sleep(100);
    // Send a very simple HTTP get (it MUST be simple, no auth, no proxy, no 302, no 401, ...)
    // Send it to another route. Must be a keepalive.
    final HttpContext context2 = HttpClientContext.create();
    client.execute(new HttpHost("127.0.0.1", target.getPort()), new HttpGet("/"), context2, response -> {
        EntityUtils.consume(response.getEntity());
        return null;
    });
    // ConnPoolByRoute now has 2 free connexions, out of its 2 max.
    // The [localhost][stuff] RouteSpcfcPool is the same as earlier
    // And there is a [127.0.0.1][null] pool with 1 free connection
    Thread.sleep(100);
    // This will put the ConnPoolByRoute to the targeted state :
    // [localhost][stuff] will not get reused because this call is [localhost][null]
    // So the ConnPoolByRoute will need to kill one connection (it is maxed out globally).
    // The killed conn is the oldest, which means the first HTTPGet ([localhost][stuff]).
    // When this happens, the RouteSpecificPool becomes empty.
    final HttpContext context3 = HttpClientContext.create();
    client.execute(target, new HttpGet("/"), context3, response -> {
        EntityUtils.consume(response.getEntity());
        return null;
    });
    // If the ConnPoolByRoute did not behave coherently with the RouteSpecificPool
    // this may fail. Ex : if the ConnPool discared the route pool because it was empty,
    // but still used it to build the request3 connection.
}

